class Account {
    private int balance;          // field: data of each object
    Account(int start) {          // constructor: runs when the object is born
        this.balance = start;
    }
    int balance() { return balance; }
}
Account a = new Account(10);
Account b = new Account(99);      // independent from a

abstract class Game {
    final void play() {          // order is fixed
        start(); turn(); end();
    }
    void start() { }             // optional step
    abstract void turn();        // each game fills this
    void end() { }
}

class Car {
    private final Engine engine;      // has-a
    Car(Engine engine) { this.engine = engine; }
    void start() { engine.ignite(); } // delegates
}

static int value() {
    int x = 1;
    try { x = 2; return x; }   // result 2 is saved first
    finally { x = 3; }         // too late to change it
}                              // returns 2

interface Priced { price: number }
class Book { constructor(public price: number) {} }
const items: Priced[] = [new Book(10), { price: 5 }];   // both accepted
